--
-- Table structure for table `ai_dispatch_log`
--

DROP TABLE IF EXISTS `ai_dispatch_log`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `ai_dispatch_log` (
  `id` int NOT NULL AUTO_INCREMENT,
  `emergency_id` int DEFAULT NULL,
  `call_id` int DEFAULT NULL,
  `recommendation_id` int DEFAULT NULL,
  `analysis_id` int DEFAULT NULL,
  `human_decision` varchar(40) COLLATE utf8mb4_unicode_ci DEFAULT '',
  `operator_id` int DEFAULT NULL,
  `payload` json DEFAULT NULL,
  `created_at` datetime NOT NULL,
  PRIMARY KEY (`id`),
  KEY `idx_ai_dlog_emergency` (`emergency_id`),
  KEY `idx_ai_dlog_created` (`created_at`),
  KEY `idx_ai_dlog_call` (`call_id`),
  KEY `idx_ai_dlog_recommendation` (`recommendation_id`),
  KEY `idx_ai_dlog_analysis` (`analysis_id`),
  KEY `idx_ai_dlog_operator` (`operator_id`),
  CONSTRAINT `fk_ai_dlog_analysis` FOREIGN KEY (`analysis_id`) REFERENCES `ai_analysis` (`id`) ON DELETE SET NULL,
  CONSTRAINT `fk_ai_dlog_call` FOREIGN KEY (`call_id`) REFERENCES `call_center_calls` (`id`) ON DELETE SET NULL,
  CONSTRAINT `fk_ai_dlog_emergency` FOREIGN KEY (`emergency_id`) REFERENCES `emergencies` (`id`) ON DELETE SET NULL,
  CONSTRAINT `fk_ai_dlog_operator` FOREIGN KEY (`operator_id`) REFERENCES `users` (`id`) ON DELETE SET NULL,
  CONSTRAINT `fk_ai_dlog_recommendation` FOREIGN KEY (`recommendation_id`) REFERENCES `ai_recommendation` (`id`) ON DELETE SET NULL
) ENGINE=InnoDB AUTO_INCREMENT=49 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

