--
-- Table structure for table `ai_memory`
--

DROP TABLE IF EXISTS `ai_memory`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `ai_memory` (
  `id` int NOT NULL AUTO_INCREMENT,
  `event_type` varchar(40) COLLATE utf8mb4_unicode_ci NOT NULL,
  `emergency_id` int DEFAULT NULL,
  `call_id` int DEFAULT NULL,
  `analysis_id` int DEFAULT NULL,
  `recommendation_id` int DEFAULT NULL,
  `dispatch_log_id` int DEFAULT NULL,
  `payload` json DEFAULT NULL,
  `timestamp` datetime NOT NULL,
  PRIMARY KEY (`id`),
  KEY `idx_ai_mem_type` (`event_type`),
