--
-- Table structure for table `ai_recommendation`
--

DROP TABLE IF EXISTS `ai_recommendation`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `ai_recommendation` (
  `id` int NOT NULL AUTO_INCREMENT,
  `analysis_id` int DEFAULT NULL,
  `emergency_id` int DEFAULT NULL,
  `call_id` int DEFAULT NULL,
  `status` varchar(20) COLLATE utf8mb4_unicode_ci DEFAULT 'pending',
  `confidence` double DEFAULT '0',
  `estimated_arrival_minutes` int DEFAULT NULL,
  `provider` varchar(40) COLLATE utf8mb4_unicode_ci DEFAULT 'rule_based',
  `human_decision` varchar(40) COLLATE utf8mb4_unicode_ci DEFAULT '',
  `operator_id` int DEFAULT NULL,
  `payload` json DEFAULT NULL,
  `created_at` datetime NOT NULL,
  `updated_at` datetime DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `idx_ai_rec_emergency` (`emergency_id`),
  KEY `idx_ai_rec_call` (`call_id`),
  KEY `idx_ai_rec_status` (`status`),
  KEY `idx_ai_rec_created` (`created_at`),
  KEY `idx_ai_rec_analysis` (`analysis_id`),
  KEY `idx_ai_rec_operator` (`operator_id`),
  CONSTRAINT `fk_ai_rec_analysis` FOREIGN KEY (`analysis_id`) REFERENCES `ai_analysis` (`id`) ON DELETE SET NULL,
  CONSTRAINT `fk_ai_rec_call` FOREIGN KEY (`call_id`) REFERENCES `call_center_calls` (`id`) ON DELETE SET NULL,
  CONSTRAINT `fk_ai_rec_emergency` FOREIGN KEY (`emergency_id`) REFERENCES `emergencies` (`id`) ON DELETE SET NULL,
  CONSTRAINT `fk_ai_rec_operator` FOREIGN KEY (`operator_id`) REFERENCES `users` (`id`) ON DELETE SET NULL
) ENGINE=InnoDB AUTO_INCREMENT=71 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

