--
-- Table structure for table `call_center_calls`
--

DROP TABLE IF EXISTS `call_center_calls`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `call_center_calls` (
  `id` int NOT NULL AUTO_INCREMENT,
  `user_id` int DEFAULT NULL,
  `caller_name` varchar(120) COLLATE utf8mb4_unicode_ci NOT NULL,
  `phone` varchar(40) COLLATE utf8mb4_unicode_ci DEFAULT '',
  `latitude` double DEFAULT NULL,
  `longitude` double DEFAULT NULL,
  `address` text COLLATE utf8mb4_unicode_ci,
  `district` varchar(120) COLLATE utf8mb4_unicode_ci DEFAULT '',
  `status` varchar(40) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'ringing',
  `operator_id` int DEFAULT NULL,
  `operator_name` varchar(120) COLLATE utf8mb4_unicode_ci DEFAULT '',
  `emergency_type` varchar(40) COLLATE utf8mb4_unicode_ci DEFAULT '',
  `emergency_types` json DEFAULT NULL,
  `dispatched_to` json DEFAULT NULL,
  `emergency_ids` json DEFAULT NULL,
  `nearest` json DEFAULT NULL,
  `device_info` json DEFAULT NULL,
  `notes` text COLLATE utf8mb4_unicode_ci,
  `accuracy_m` double DEFAULT NULL,
  `start_time` datetime NOT NULL,
  `answered_at` datetime DEFAULT NULL,
  `dispatched_at` datetime DEFAULT NULL,
  `end_time` datetime DEFAULT NULL,
  `duration_sec` int DEFAULT '0',
  `final_status` varchar(40) COLLATE utf8mb4_unicode_ci DEFAULT '',
  `source` varchar(40) COLLATE utf8mb4_unicode_ci DEFAULT 'call_center',
  `voice_mode` tinyint(1) DEFAULT '0',
  `ended_by` varchar(40) COLLATE utf8mb4_unicode_ci DEFAULT '',
  `media_connected_at` datetime DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `idx_cc_status` (`status`),
  KEY `idx_cc_operator` (`operator_id`),
  KEY `idx_cc_user` (`user_id`),
  KEY `idx_cc_start` (`start_time`),
  KEY `idx_cc_status_start` (`status`,`start_time`),
  CONSTRAINT `fk_cc_operator` FOREIGN KEY (`operator_id`) REFERENCES `users` (`id`) ON DELETE SET NULL,
  CONSTRAINT `fk_cc_user` FOREIGN KEY (`user_id`) REFERENCES `users` (`id`) ON DELETE SET NULL
) ENGINE=InnoDB AUTO_INCREMENT=66 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

