--
-- Table structure for table `call_centers`
--

DROP TABLE IF EXISTS `call_centers`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `call_centers` (
  `id` int NOT NULL AUTO_INCREMENT,
  `name` varchar(180) COLLATE utf8mb4_unicode_ci NOT NULL,
  `city` varchar(80) COLLATE utf8mb4_unicode_ci DEFAULT '',
  `region` varchar(80) COLLATE utf8mb4_unicode_ci DEFAULT '',
  `district` varchar(80) COLLATE utf8mb4_unicode_ci DEFAULT '',
  `address` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT '',
  `latitude` double DEFAULT NULL,
  `longitude` double DEFAULT NULL,
  `phone` varchar(40) COLLATE utf8mb4_unicode_ci DEFAULT '',
  `operating_status` enum('open','limited','closed') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'open',
  `owner_user_id` int DEFAULT NULL,
  `created_at` datetime NOT NULL,
  `updated_at` datetime NOT NULL,
  PRIMARY KEY (`id`),
  KEY `idx_cc_fac_status` (`operating_status`),
  KEY `idx_cc_fac_city` (`city`),
  KEY `idx_cc_fac_owner` (`owner_user_id`),
  CONSTRAINT `fk_cc_fac_owner` FOREIGN KEY (`owner_user_id`) REFERENCES `users` (`id`) ON DELETE SET NULL
) ENGINE=InnoDB AUTO_INCREMENT=17 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

