--
-- Table structure for table `emergencies`
--

DROP TABLE IF EXISTS `emergencies`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `emergencies` (
  `id` int NOT NULL AUTO_INCREMENT,
  `user_id` int DEFAULT NULL,
  `type` varchar(40) COLLATE utf8mb4_unicode_ci NOT NULL,
  `status` varchar(40) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'pending',
  `location` text COLLATE utf8mb4_unicode_ci,
  `district` varchar(120) COLLATE utf8mb4_unicode_ci DEFAULT '',
  `latitude` double DEFAULT NULL,
  `longitude` double DEFAULT NULL,
  `notes` text COLLATE utf8mb4_unicode_ci,
  `caller_name` varchar(120) COLLATE utf8mb4_unicode_ci DEFAULT '',
  `phone` varchar(40) COLLATE utf8mb4_unicode_ci DEFAULT '',
  `assigned_to` varchar(40) COLLATE utf8mb4_unicode_ci DEFAULT 'hospital',
  `assigned_team_label` varchar(120) COLLATE utf8mb4_unicode_ci DEFAULT '',
  `assigned_hospital_id` int DEFAULT NULL,
  `assigned_hospital_name` varchar(180) COLLATE utf8mb4_unicode_ci DEFAULT '',
  `hospital_distance_km` double DEFAULT NULL,
  `tracking_active` tinyint(1) DEFAULT '0',
  `last_location_update` datetime DEFAULT NULL,
  `accepted_at` datetime DEFAULT NULL,
  `timestamp` datetime NOT NULL,
  `payload` json DEFAULT NULL,
  `assigned_station_id` int DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `idx_emergencies_user` (`user_id`),
  KEY `idx_emergencies_status` (`status`),
  KEY `idx_emergencies_hospital` (`assigned_hospital_id`),
  KEY `idx_emergencies_timestamp` (`timestamp`),
  KEY `idx_emergencies_status_ts` (`status`,`timestamp`),
  KEY `idx_emergencies_type_status` (`type`,`status`),
  KEY `fk_emergencies_station` (`assigned_station_id`),
  CONSTRAINT `fk_emergencies_hospital` FOREIGN KEY (`assigned_hospital_id`) REFERENCES `hospitals` (`id`) ON DELETE SET NULL,
  CONSTRAINT `fk_emergencies_station` FOREIGN KEY (`assigned_station_id`) REFERENCES `response_stations` (`id`) ON DELETE SET NULL,
  CONSTRAINT `fk_emergencies_user` FOREIGN KEY (`user_id`) REFERENCES `users` (`id`) ON DELETE SET NULL
) ENGINE=InnoDB AUTO_INCREMENT=80 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

