DROP TABLE IF EXISTS `hospitals`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `hospitals` (
  `id` int NOT NULL AUTO_INCREMENT,
  `name` varchar(180) COLLATE utf8mb4_unicode_ci NOT NULL,
  `city` varchar(80) COLLATE utf8mb4_unicode_ci DEFAULT '',
  `region` varchar(80) COLLATE utf8mb4_unicode_ci DEFAULT '',
  `district` varchar(80) COLLATE utf8mb4_unicode_ci DEFAULT '',
  `address` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT '',
  `latitude` double NOT NULL,
  `longitude` double NOT NULL,
  `phone` varchar(40) COLLATE utf8mb4_unicode_ci DEFAULT '',
  `emergency_contacts` json DEFAULT NULL,
  `services` json DEFAULT NULL,
  `specialties` json DEFAULT NULL,
  `ambulance_available` tinyint(1) DEFAULT '0',
  `ambulance_count` int DEFAULT '0',
  `emergency_capacity` int DEFAULT '10',
  `rating` double DEFAULT '4',
  `operating_status` enum('open','limited','closed') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'open',
  `contact_email` varchar(180) COLLATE utf8mb4_unicode_ci DEFAULT '',
  `owner_user_id` int DEFAULT NULL,
  `location_verified` tinyint(1) DEFAULT '0',
  `logo_url` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT '',
  `created_at` datetime NOT NULL,
  `updated_at` datetime NOT NULL,
  PRIMARY KEY (`id`),
  KEY `idx_hospitals_region` (`region`),
  KEY `idx_hospitals_city` (`city`),
  KEY `idx_hospitals_status` (`operating_status`),
  KEY `fk_hospitals_owner` (`owner_user_id`),
  CONSTRAINT `fk_hospitals_owner` FOREIGN KEY (`owner_user_id`) REFERENCES `users` (`id`) ON DELETE SET NULL
) ENGINE=InnoDB AUTO_INCREMENT=10 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

