DROP TABLE IF EXISTS `messages`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `messages` (
  `id` int NOT NULL AUTO_INCREMENT,
  `request_id` int NOT NULL,
  `sender_role` varchar(20) COLLATE utf8mb4_unicode_ci NOT NULL,
  `sender_id` int DEFAULT NULL,
  `text` mediumtext COLLATE utf8mb4_unicode_ci NOT NULL,
  `msg_type` varchar(20) COLLATE utf8mb4_unicode_ci DEFAULT 'text',
  `status` varchar(20) COLLATE utf8mb4_unicode_ci DEFAULT 'sent',
  `timestamp` datetime NOT NULL,
  `delivered_at` datetime DEFAULT NULL,
  `seen_at` datetime DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `idx_messages_request` (`request_id`),
  KEY `idx_messages_sender` (`sender_id`),
  KEY `idx_messages_request_ts` (`request_id`,`timestamp`),
  CONSTRAINT `fk_messages_request` FOREIGN KEY (`request_id`) REFERENCES `emergencies` (`id`) ON DELETE CASCADE,
  CONSTRAINT `fk_messages_sender` FOREIGN KEY (`sender_id`) REFERENCES `users` (`id`) ON DELETE SET NULL
) ENGINE=InnoDB AUTO_INCREMENT=106 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
