--
-- Table structure for table `notifications`
--

DROP TABLE IF EXISTS `notifications`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `notifications` (
  `id` int NOT NULL AUTO_INCREMENT,
  `target_type` varchar(20) COLLATE utf8mb4_unicode_ci NOT NULL,
  `target_id` int NOT NULL,
  `message` text COLLATE utf8mb4_unicode_ci NOT NULL,
  `ntype` varchar(40) COLLATE utf8mb4_unicode_ci DEFAULT 'system_alert',
  `request_id` int DEFAULT NULL,
  `is_read` tinyint(1) DEFAULT '0',
  `timestamp` datetime NOT NULL,
  PRIMARY KEY (`id`),
  KEY `idx_notif_target` (`target_type`,`target_id`),
  KEY `idx_notif_request` (`request_id`),
  KEY `idx_notif_read` (`is_read`),
  KEY `idx_notif_target_read` (`target_type`,`target_id`,`is_read`),
  CONSTRAINT `fk_notif_request` FOREIGN KEY (`request_id`) REFERENCES `emergencies` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=1144 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

